def apply_deepening(cards,evidence,category_rows):
 by={c['card_id']:c for c in cards}
 for number,publisher,title,url,locator,date,cache in SOURCES:
  eid='EDP-'+number
  yr=2023 if number=='03' else 2024 if number in ['04','10','16','27','32'] else 2025 if number in ['13','14'] else 2026
  evidence[eid]=dict(evidence_id=eid,publisher=publisher,year=yr,title=title,url=url,locator=locator,published_date=date,checked_date='2026-10-16',evidence_type='企業／開発元公式説明・メーカー主張' if number!='11' else '企業公式サイトに掲載された顧客発言',exhibition_certainty='製品・技術説明／他展示会・実証を含む。JIMTOF2026の展示確定とは別',cache_path=f'sources/priority_deepening/{cache}.json',source_excerpt=locator,retrieval_note='webの抽出／検索索引をキャッシュ。原ページ全文の保存ではない。EDP-02はPDF容量超過、EDP-11は本文抽出不可で検索索引の該当記述を確認。')
 changed=[]
 for review in REVIEWS:
  c=by[review['card_id']];d=dict(review)
  d['source_ids']=[eid for eid in d['source_ids'] if eid]
  d['source_status']=d.get('source_status','企業・開発元の補足公式資料を確認')
  c['deepening']=d
  c['input']=d['ai_input'];c['mechanism']=d['ai_judgment'];c['output']=d['execution']
  c['human_boundary']='事前準備：'+d['human_preparation']+'／承認：'+d['human_approval']+'／例外対応：'+d['human_exception']
  for key in ['baseline_2024','observation_2026','delta_type','delta_interpretation','product_stage','system_configuration']:
   if key in d:c[key]=d[key]
  c['unresolved']=d['limits']+' 現地質問：'+c['unresolved']
  for eid in d['source_ids']:
   assert eid in evidence,eid
   if eid not in c['evidence_ids']:
    c['evidence_ids'].append(eid)
    c['source_locations'].append(dict(evidence_id=eid,url=evidence[eid]['url'],locator=evidence[eid]['locator']))
  changed.append(dict(card_id=c['card_id'],company=c['company'],item=c['item'],booths_2026=c['booths_2026'],**{k:d[k] for k in ['ai_scope','ai_input','ai_judgment','execution','human_preparation','human_approval','human_exception','limits','source_status']},baseline_2024=c['baseline_2024'],observation_2026=c['observation_2026'],delta_type=c['delta_type'],delta_interpretation=c['delta_interpretation'],product_stage=c['product_stage'],evidence_ids=c['evidence_ids'],source_urls=[evidence[e]['url'] for e in c['evidence_ids']],checked_date='2026-10-16'))
 for r in category_rows:
  c=by[r['card_id']]
  if 'deepening' not in c:continue
  r['output']=c['output'];r['product_stage']=c['product_stage']
  r['evidence_ids']=list(dict.fromkeys(r['evidence_ids']+c['deepening']['source_ids']))
  r['source_urls']=list(dict.fromkeys(evidence[e]['url'] for e in r['evidence_ids']))
 assert len(changed)==33 and len({r['company'] for r in changed})==28
 return changed,dict(companies=28,items=33,new_official_source_records=len(SOURCES),supplemented_companies=26,catalogue_only_companies=2,source_status_counts=dict(Counter(r['source_status'] for r in changed)),retrieval_scope='web本文抽出・検索索引で該当箇所を確認。原ページ全文を取得した件数ではない。',retrieval_limits=[dict(evidence_id='EDP-01',result='LP本文はCache miss。公式LPの検索索引にある2024出展等を確認'),dict(evidence_id='EDP-02',result='公式PDF本体は10MiB超過で取得不可。検索索引のGH5仕様記述を確認'),dict(evidence_id='EDP-11',result='公式導入事例の本文抽出は0行。検索索引の読取り・人の補正の説明を確認'),dict(evidence_id='EDP-27',result='公式出展報告本文は取得エラー。検索索引の2024初披露品一覧を確認')],remaining=['ツールディスカバリーのAI算定方式とALFREDの補足技術資料は未確認','判断から指令への権限・人の承認・失敗復帰は未公開箇所が残る','2024同名出展資料不足と法人別名の照合は未完了','2026展示予定と他会場・国外実証の機能を区別。現地実機・成功率・採用件数は未検証'],checked_date='2026-10-16')
